import re

_UNITS = {}
for _names, _secs in [
    (("s", "sec", "secs", "second", "seconds"), 1),
    (("m", "min", "mins", "minute", "minutes"), 60),
    (("h", "hr", "hrs", "hour", "hours"), 3600),
    (("d", "day", "days"), 86400),
    (("w", "wk", "wks", "week", "weeks"), 604800),
]:
    for _n in _names:
        _UNITS[_n] = _secs

_NUM = r"(?:\d+(?:\.\d*)?|\.\d+)"
_ISO = re.compile(
    rf"P(?:({_NUM})W)?(?:({_NUM})D)?(?:T(?:({_NUM})H)?(?:({_NUM})M)?(?:({_NUM})S)?)?"
)
_COMPONENT = re.compile(rf"\s*({_NUM})\s*([a-z]+)\s*")


def _round(total: float) -> int:
    if total < 0:
        raise ValueError("negative duration")
    return int(total + 0.5)


def parse_duration(text: str) -> int:
    """Return the duration described by `text` in whole seconds. See README.md."""
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    s = text.strip()
    if not s:
        raise ValueError("empty duration")

    if re.fullmatch(r"\d+", s):
        return int(s)

    # ISO 8601
    if s[:1] in "Pp":
        m = _ISO.fullmatch(s.upper())
        if not m or s.upper() in ("P", "PT") or s.upper().endswith("T"):
            raise ValueError(f"invalid ISO 8601 duration: {text!r}")
        mult = (604800, 86400, 3600, 60, 1)
        return _round(sum(float(g) * k for g, k in zip(m.groups(), mult) if g))

    # Clock notation
    if ":" in s:
        parts = s.split(":")
        if len(parts) not in (2, 3) or not all(re.fullmatch(r"\d+", p) for p in parts[:-1]) \
                or not re.fullmatch(_NUM, parts[-1]):
            raise ValueError(f"invalid clock duration: {text!r}")
        if len(parts) == 2:
            h, mi, sec = 0, int(parts[0]), float(parts[1])
        else:
            h, mi, sec = int(parts[0]), int(parts[1]), float(parts[2])
        if len(parts) == 3 and mi >= 60 or sec >= 60:
            raise ValueError(f"invalid clock duration: {text!r}")
        return _round(h * 3600 + mi * 60 + sec)

    # Number+unit components
    low = s.lower()
    pos = 0
    total = 0.0
    while pos < len(low):
        m = _COMPONENT.match(low, pos)
        if not m or m.end() == pos:
            raise ValueError(f"invalid duration: {text!r}")
        unit = m.group(2)
        if unit not in _UNITS:
            raise ValueError(f"unknown unit {unit!r} in {text!r}")
        total += float(m.group(1)) * _UNITS[unit]
        pos = m.end()
    return _round(total)

